query Query($inventoryNumber: String!, $unitId: String!) {
  inventory(where: {number:{_eq:$inventoryNumber} active:{_eq:true}}) {
    edges {
      node {
        id
				active
        barcode
        number
        trackingNumber
        location {
          id
          name
          locationType {
            id
            name

            qualityHold
          }
        }
        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight

        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            containment

          }
        }
        supplier {
          id
          name
          externalId
          status
        }
        productStrategyProcess {
          id
          code          
          unitWeight
          productStrategy {
            id
            code
            name
            product {
              id
              code
              name
            }
          }
        }
      }
    }
  }
  productionSetupMaterial(where:{inventory:{number:{_eq:$inventoryNumber}}}) {
    edges {
      node {
        id
        number
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  }
  transactionType(where:{inventoryAdjustment:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
  unit(where:{id:{_eq:$unitId}}) {
    edges {
      node {
        id
      }
    }
  }
}

